import { spawnSync } from 'node:child_process';

import { EXECUTABLE_PATH, MAX_BUFFER_BYTES } from './constants.mjs';

function emptyBuffer() {
  return Buffer.alloc(0);
}

export function invokeExecutable(args) {
  const result = spawnSync(EXECUTABLE_PATH, args, {
    encoding: null,
    maxBuffer: MAX_BUFFER_BYTES,
    stdio: ['ignore', 'pipe', 'pipe'],
  });

  if (result.error) {
    throw result.error;
  }

  return {
    stdout: result.stdout ?? emptyBuffer(),
    stderr: result.stderr ?? emptyBuffer(),
    status: result.status ?? 1,
  };
}

export function buildTransformArgs(aValue) {
  return ['--a', aValue];
}

