import { parseCliArgs } from './argv.mjs';
import { buildTransformArgs, invokeExecutable } from './executable.mjs';

function writeStream(stream, chunk) {
  if (chunk.length > 0) {
    stream.write(chunk);
  }
}

export function runCli(rawArgs, io = process) {
  const parsed = parseCliArgs(rawArgs);
  const executableArgs =
    parsed.kind === 'run' ? buildTransformArgs(parsed.aValue) : rawArgs;
  const result = invokeExecutable(executableArgs);

  writeStream(io.stdout, result.stdout);
  writeStream(io.stderr, result.stderr);

  return result.status;
}

